js:function(context, args) {
  var actor = args && args.actor;
  if (actor === undefined || actor === null || actor === '') {
    return {defer: 'missing current arguments', parameters: 'actor (string): the actor value to submit the experiment for'};
  }
  function grabId(x) {
    if (!x) return null;
    if (x.data && x.data.native_operation_id) return x.data.native_operation_id;
    var m = (x.text || '').match(/"native_operation_id"\s*:\s*"([^"]+)"/);
    return m ? m[1] : null;
  }
  var h = (context && context.history) || [];
  var submittedCall = null, opId = null, terminal = null;
  for (var i = 0; i < h.length; i++) {
    var argv = h[i].decoded_argv || [];
    if (argv[0] !== 'experiment') continue;
    if (argv[1] === 'submit' || argv[1] === 'append') {
      submittedCall = h[i];
      var g = grabId(h[i]);
      if (g) opId = g;
    } else if (argv[1] === 'status') {
      var g2 = grabId(h[i]);
      if (g2) opId = g2;
      if (h[i].data && h[i].data.complete === true && h[i].data.native_operation_id === opId) terminal = h[i];
    }
  }
  if (!submittedCall) {
    var sub = execute({name: 'bash', arguments: {command: command('experiment', ['submit', actor])}, read: false, step: 'submit', occurrence: 0});
    var subId = grabId(sub);
    if (subId) opId = subId;
    if (!opId) return {defer: 'experiment submit dispatched but native operation id not recoverable: ' + ((sub && sub.text) || '')};
  }
  if (!opId) return {defer: 'no native operation id available to inspect'};
  if (terminal) {
    return {report: {native_operation_id: terminal.data.native_operation_id, receipt: terminal.data.receipt}};
  }
  for (var k = 0; k < 60; k++) {
    var st = execute({name: 'bash', arguments: {command: command('experiment', ['status', opId])}, read: true});
    if (st && st.is_error) return {defer: 'status inspection failed for ' + opId + ': ' + (st.text || '')};
    var sdata = st && st.data;
    var sid = grabId(st);
    if (sid) opId = sid;
    if (sdata && sdata.complete === true) return {report: {native_operation_id: sdata.native_operation_id, receipt: sdata.receipt}};
  }
  return {defer: 'experiment ' + opId + ' not complete after repeated fresh inspection'};
}
